FUNCTION_BLOCK FB
VAR_INPUT
    flowLow   : BOOL;
    ackBtn    : BOOL;
    sensorOK  : BOOL;
END_VAR
VAR_OUTPUT
    alarmActive  : BOOL;
    alarmAcked   : BOOL;
    highHigh     : BOOL;
END_VAR
VAR
    prev_flowLow  : BOOL := FALSE;
    prev_ackBtn   : BOOL := FALSE;
END_VAR
// ENGINEERING_CONTRACT
// State machine: Four-state alarm model per ISA-18.2
// alarmActive: LATCHED until acknowledged then cleared (PUB001, PUB005, PUB006, PUB007)
// alarmAcked:  SET on rising ackBtn while condition present OR when condition clears
//              while unacknowledged (PUB005, PUB006, PUB007); clears with alarmActive
// highHigh:    UNLATCHED, direct sensorOK inverse (PUB004, PUB008)
// State table:
//   Condition present & unacked  -> alarmActive=TRUE, alarmAcked=FALSE
//   Condition present & acked    -> alarmActive=TRUE, alarmAcked=TRUE
//   Condition cleared & unacked  -> alarmActive=TRUE, alarmAcked=TRUE (pending clear)
//   Rising ackBtn in cleared     -> alarmActive=FALSE, alarmAcked=FALSE
// Scan order: alarmActive/alarmAcked first, then rising-edge check, then sensor.
// CONTRACT_RULES [{"kind": "hold_until_reset", "output": "alarmActive", "set_input": "flowLow", "reset_input": "ackBtn"}]

alarmActive := flowLow OR (alarmActive AND NOT (NOT flowLow AND alarmAcked));
alarmAcked  := (NOT flowLow AND alarmActive AND NOT prev_flowLow) OR (prev_flowLow AND alarmActive);

IF (NOT prev_ackBtn AND ackBtn) THEN
    IF NOT flowLow THEN
        alarmActive := FALSE;
        alarmAcked  := FALSE;
    ELSE
        alarmAcked := TRUE;
    END_IF;
END_IF;

prev_flowLow := flowLow;
prev_ackBtn  := ackBtn;
highHigh     := NOT sensorOK;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB
VAR_INPUT
    flowLow   : BOOL;
    ackBtn    : BOOL;
    sensorOK  : BOOL;
END_VAR
VAR_OUTPUT
    alarmActive  : BOOL;
    alarmAcked   : BOOL;
    highHigh     : BOOL;
END_VAR
VAR
    prev_flowLow : BOOL := FALSE;
    prev_ackBtn  : BOOL := FALSE;
END_VAR
// ENGINEERING_CONTRACT
// State machine: Four-state alarm model per ISA-18.2
// State transitions:
//   S1 (fresh alarm):    flowLow rises          -> alarmActive=TRUE, alarmAcked=FALSE
//   S2 (pending-clear):  flowLow falls (unacked) -> alarmActive=TRUE, alarmAcked=TRUE
//   S3 (cleared):        rising ackBtn in S2    -> alarmActive=FALSE, alarmAcked=FALSE
//   S4 (re-alarm):       flowLow rises in S2    -> alarmActive=TRUE, alarmAcked=FALSE
// Scan order: rising-edge flags computed first, then alarmActive/alarmAcked, then sensor.
// CONTRACT_RULES [{"kind": "hold_until_reset", "output": "alarmActive", "set_input": "flowLow", "reset_input": "ackBtn"}]

// Rising-edge detection (must precede assignments to avoid circular dependency)
VAR_TEMP
    rising_flowLow : BOOL;
    rising_ackBtn  : BOOL;
END_VAR

rising_flowLow := flowLow AND NOT prev_flowLow;
rising_ackBtn  := ackBtn  AND NOT prev_ackBtn;

// alarmActive: persists through pending-clear (prev_flowLow AND alarmAcked)
// alarmAcked:  set on falling flowLow while active; reset on rising flowLow or rising ackBtn

alarmActive := flowLow OR (alarmActive AND (flowLow OR (prev_flowLow AND alarmAcked)));
alarmAcked  := (rising_flowLow AND alarmActive) OR (NOT flowLow AND alarmActive) OR (rising_ackBtn AND alarmActive);

// Update previous-state flags
prev_flowLow := flowLow;
prev_ackBtn  := ackBtn;

// High-priority sensor-failure alarm (unlatched, direct inverse of sensorOK)
highHigh := NOT sensorOK;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB
VAR_INPUT
    flowLow   : BOOL;
    ackBtn    : BOOL;
    sensorOK  : BOOL;
END_VAR
VAR_OUTPUT
    alarmActive  : BOOL;
    alarmAcked   : BOOL;
    highHigh     : BOOL;
END_VAR
VAR
    prev_flowLow     : BOOL := FALSE;
    prev_ackBtn      : BOOL := FALSE;
    prev_alarmActive : BOOL := FALSE;
END_VAR
// ENGINEERING_CONTRACT
// State machine: Four-state alarm model per ISA-18.2
// alarmActive: LATCHED until acknowledged then cleared (PUB001, PUB005, PUB006, PUB007)
// alarmAcked:  SET when condition clears while alarmActive (pending clear) OR
//              on rising ackBtn while alarmActive; TRUE when condition present and
//              previously acknowledged (PUB005, PUB006, PUB007)
// highHigh:    UNLATCHED, direct sensorOK inverse (PUB004, PUB008)
// Scan order: alarmActive first, then rising-edge check, then sensor.
// CONTRACT_RULES [{"kind": "hold_until_reset", "output": "alarmActive", "set_input": "flowLow", "reset_input": "ackBtn"}]

alarmActive := flowLow OR (alarmActive AND NOT (NOT flowLow AND alarmAcked));

IF (NOT prev_ackBtn AND ackBtn) THEN
    IF NOT flowLow THEN
        alarmActive := FALSE;
        alarmAcked  := FALSE;
    ELSE
        alarmAcked := TRUE;
    END_IF;
END_IF;

alarmAcked := alarmAcked OR (NOT flowLow AND alarmActive AND prev_flowLow AND prev_alarmActive);

prev_alarmActive := alarmActive;
prev_flowLow     := flowLow;
prev_ackBtn      := ackBtn;
highHigh         := NOT sensorOK;
END_FUNCTION_BLOCK
